          en: "FitMesh reads Wear OS data through Android Health Connect. Grant FitMesh read permissions in the Health Connect app, then tap 'Sync' in FitMesh. Your watch syncs automatically as long as its companion app (Pixel Watch app, Galaxy Watch app, etc.) writes data to Health Connect.",
