          pt: "O FitMesh lê os dados do Wear OS através do Android Health Connect. conceda permissões de leitura ao FitMesh no aplicativo Health Connect, depois toque em 'Sincronizar' no FitMesh. Seu relógio sincroniza automaticamente desde que seu aplicativo complementar (aplicativo Pixel Watch, aplicativo Galaxy Watch, etc.) grava dados para o Health Connect.",
          fr: "FitMesh lit les données Wear OS via Health Connect d'Android. Donnez l'autorisation de lecture à FitMesh dans l'application Health Connect, puis appuyez sur 'Synchroniser' dans FitMesh. Votre montre se synchronise automatiquement tant que son application associée (application de la Pixel Watch, application de la Galaxy Watch, etc.) envoie des données vers Health Connect.",
          pl: "FitMesh odczytuje dane z zegarów Wear OS poprzez Android Health Connect. Zezwól na odczyt danych w aplikacji Health Connect, a następnie naciśnij 'Synchronizuj' w FitMesh. Twoi zegarze synchronizują się automatycznie, pod warunkiem że ich powiązane aplikacje (np. Galaxy Watch app, Pixel Watch app) zapisują dane do Health Connect.",
          tr: "FitMesh, Wear OS verileri Android Health Connect aracılığıyla okuyar. FitMesh'e okuma izni vermek için Health Connect uygulamasında izinleri kabul edin, ardından FitMesh'de 'Sinc' butonuna tıklayın. Cüzdanınız, eşitliğinHealth Connect'teki verilerle yazıldığı sürece otomatik olarak bağlanır.",
          nl: "FitMesh leest Wear OS-data via Android Health Connect af. Geef FitMesh de lees-permissies in het Health Connect-apparaat, dan tik je op 'Sync' in FitMesh. Je horloge synchroniseert automatisch zolang het bijbehorende apparaat (Pixel Watch-app, Galaxy Watch-app, etc.) data naar Health Connect schrijft.",
          ja: "FitMeshはAndroid Health Connectを通じてWear OSのデータを読み取ります。Health ConnectアプリでFitMeshに読み取り権限を付与し、FitMeshで「Sync（同期）」をタップしてください。スマートウォッチのコンパニオンアプリ（Pixel Watchアプリ、Galaxy Watchアプリなど）がHealth Connectにデータを書き込む限り、スマートウォッチは自動的に同期されます。",
          ko: "FitMesh는 Android Health Connect를 통해 Wear OS 데이터를 읽습니다. Health Connect 앱에서 FitMesh의 읽기 권한을 허용한 후 FitMesh에서 'Sync'를 탭하세요. 동반 앱(Pixel Watch 앱, Galaxy Watch 앱 등)이 Health Connect에 데이터를 쓰는 한 웨어러가 자동으로 동기화됩니다.",
