          en: "Wear OS watches sync data to Health Connect in batches, so there may be a small delay. Also, if multiple devices track steps simultaneously, FitMesh de-duplicates them using the Health Connect priority rules. Check Health Connect settings to ensure your watch is set as the preferred step source.",
          es: "Los relojes Wear OS envían datos a Health Connect en lotes, por lo que puede haber un pequeño retraso. También, si múltiples dispositivos rastrean los pasos simultáneamente, FitMesh duplica los datos usando las reglas de prioridad de Health Connect. Comprueba las configuraciones de Health Connect para asegurarte de que tu reloj está establecido como la fuente prioritaria de pasos.",
          de: "Wear OS-Uhren senden ihre Daten an Health Connect in Batches, sodass eine kurze Verspätung eintreten kann. Wenn mehrere Geräte gleichzeitig Schritte verfolgen, de-dupliziert FitMesh sie gemäß den Prioritätsregeln von Health Connect. Stellen Sie sicher, dass die Einstellungen in Health Connect Ihren Wunsch zur Vorzugswahl Ihrer Uhr als Quelle für die Schrittzählung erfüllen.",
          pt: "Os relógios Wear OS sincronizam os dados com o Health Connect em lotes, então pode haver um pequeno atraso. Além disso, se múltiplos dispositivos estiverem rastreando passos simultaneamente, o FitMesh desduplica eles usando as regras de prioridade do Health Connect. Verifique as configurações do Health Connect para garantir que seu relógio esteja definido como a fonte preferencial de passos.",
          fr: "Les montres Wear OS envoient les données vers Health Connect en lots, il peut y avoir donc un petit retard. De plus, si plusieurs appareils suivent simultanément le comptage des pas, FitMesh les dédouble et les corrige en utilisant les règles de priorité d'Health Connect. Vérifiez les paramètres d'Health Connect pour vous assurer que votre montre est définie comme la source préférée du comptage des pas.",
          pl: "Zegarki Wear OS synchronizują dane do Health Connect w paczkach, co może spowodować małą opóźnienie. Jeśli wielkie urządzenia śledzą kroki jednocześnie, FitMesh de-duplikuje te informacje korzystając z priorytetowych zasad Health Connect. Sprawdź ustawienia Health Connect, aby upewnić się, że twój zegar jest ustawiony jako preferowany źródło kroków.",
