          tr: "FitMesh, adımlar, kalp hızı, dinlenme kalp hızı, RMSSD (HRV), uyku aşamaları, kaloriler, uzaklık, egzersiz, SpO₂ ve VO₂ max metriklerini Health Connect üzerinden Pixel Zamanlayıcısı'dan okuyabilir. Pixel Watch 2+ 'da Fitbit uygulamasından gelen ek sağlığına dair bilgiler de dahil olmak üzere FitMesh'ü destekler.",
          nl: "FitMesh kan stappen, hartslag, rustende hartslag, HRV (RMSSD), slaapfases, kalorien, afgelegde afstand, workout en SpO₂ lezen van de Galaxy Watch via Health Connect. De Fitbit-app op de Galaxy Watch 2+ voegt ook extra gezondheidsinziendheden toe.",
          ja: "FitMeshはHealth Connect経由でPixel Watchからステップ、心拍数、安静時心拍数、HRV（RMSSD）、睡眠ステージ、カロリー、距離、ワークアウト、SpO₂、VO₂ maxを読み取れます。Pixel Watch 2+にはFitbitアプリも搭載されており、追加の健康インサイトを提供します。",
          ko: "FitMesh는 Health Connect를 통해 Pixel Watch에서 걸음수, 심박수, 휴식 심박수, HRV(RMSSD), 수면 단계, 칼로리, 거리, 운동, SpO₂, VO₂ max를 읽을 수 있습니다. Pixel Watch 2+의 Fitbit 앱은 추가 건강 정보도 제공합니다.",
