          de: "Ja. FitMesh funktioniert mit dem Pixel Watch 1, 2 und 3. Alle Modelle senden gesundheitliche Daten an Android Health Connect, den FitMesh direkt liest. Benutzer des Pixel Watch 2 und 3 profitieren auch von Fitbit-getriebenem Metrik wie Daily Readiness Score, wenn sie die Fitbit-Anwendung verwenden.",
          pt: "Sim. O FitMesh trabalha com o Galaxy Watch 1, 2 e 3. Todos os modelos sincronizam dados de saúde para o Health Connect do Android, que é lido diretamente pelo FitMesh. Os usuários do Galaxy Watch 2 e 3 também beneficiam dos métricos do Fitbit como a Pontuação de Prontidão Diária se usar a aplicação Fitbit.",
          fr: "Oui. FitMesh fonctionne avec la Galaxy Watch 1, 2 et 3. Toutes les modèles synchronisent les données de santé vers Android Health Connect, que FitMesh lit directement. Les utilisateurs de la Galaxy Watch 2 et 3 bénéficient également des métriques Fitbit comme le Score de Préparation Daily si ils utilisent l'application Fitbit.",
