          tr: "Evet. FitMesh, Pixel Zamanlayıcı 1, 2 ve 3 modelleriyle çalışmaktadır. Tüm modellerde sağlık verileriniz Android Health Connect'ı aracılığıyla senkronize edilir ve FitMesh bu verileri doğrudan okuyar. Pixel Watch 2 ve 3 kullanıcılara Daily Readiness Score gibi Fitbit destekli metriklerin de kullanılabileceği için Fitbit uygulamasını da kullanabilirsiniz.",
          nl: "Ja. FitMesh werkt met de Galaxy Watch 1, 2 en 3. Alle modellen synchroniseren gezondheidsgegevens naar Android Health Connect, wat FitMesh rechtstreeks leest. Gebruikers van de Galaxy Watch 2 en 3 voegen ook voordeel bij aan Fitbit-gerichte metrische gegevens zoals Daily Readiness Score indien ze de Fitbit-app gebruiken.",
