          nl: "Zorg ervoor dat de Mi Fitness (of Zepp Life) app Health Connect synchronisatie heeft geactiveerd en dat 'Slaap' schrijftoestemming is toegestaan. Sommige Mi Band modellen synchroniseren slechts slaapgegevens na wakker zijn en het openbaren van de app. Zodra Health Connect de gegevens heeft, worden deze door FitMesh ingevoerd bij de volgende synchronisatie.",
