          pt: "Os dados SpO₂ estão disponíveis no FitMesh se seu modelo Mi Band suportar e a aplicação Mi Fitness escreverem esses dados no Health Connect. Os dados de estresse (baseados em HRV) atualmente não são padronizados no Health Connect e podem não estar disponíveis no FitMesh.",
          fr: "Les données SpO₂ sont disponibles dans FitMesh si votre Mi Band est compatible avec elles et que l'application Mi Fitness en écrit dans Health Connect. Les données de stress (basées sur HRV) ne sont actuellement pas standardisées dans Health Connect et peuvent ne pas être disponibles dans FitMesh。",
          pl: "Dane SpO₂ będą dostępne w FitMesh, jeśli model Twojej Mi Band obsługuje je i aplikacja Mi Fitness zapisuje te dane do Health Connect. Dane dotyczące stresu (podstawowe na podstawie HRV) nie są obecnie standardowe w Health Connect i mogą się tam nie znaleźć.",
