          nl: "SpO₂-gegevens zijn beschikbaar in FitMesh indien het modellen van je Mi Band dit ondersteunen en de Mi Fitness app deze schrijft naar Health Connect. Stressgegevens (gestimeerd op basis van HRV) worden helaas nog niet standaard geïmplementeerd in Health Connect en zijn momenteel niet beschikbaar in FitMesh.",
