          en: "FitMesh works with all Amazfit watches and bands that sync to the Zepp app: GTR series, GTS series, T-Rex, Falcon, Cheetah, Balance, and Amazfit Band. All these devices write to Health Connect through Zepp, which FitMesh then reads.",
          es: "FitMesh funciona con todos los relojes y pulseras Amazfit que sincronizan con la aplicación Zepp: series GTR, series GTS, T-Rex, Falcon, Cheetah, Balance y Amazfit Band. Todos estos dispositivos escriben en Health Connect a través de Zepp, que FitMesh luego lee.",
          de: "FitMesh arbeitet mit allen Amazfit-Uhren und Armbändern, die sich an das Zepp-App-Sync anbinden: GTR-Reihe, GTS-Reihe, T-Rex, Falcon, Cheetah, Balance und Amazfit Band. Alle diese Geräte schreiben an Health Connect über das Zepp-App-Sync, das FitMesh danach liest.",
          pt: "O FitMesh funciona com todos os relógios e pulseiras Amazfit que sincronizam com o app Zepp: série GTR, série GTS, T-Rex, Falcon, Cheetah, Balance e Amazfit Band. Todos esses dispositivos escrevem no Health Connect através do Zepp, que o FitMesh lê.",
          fr: "FitMesh fonctionne avec toutes les montres et bracelets Amazfit qui synchronisent avec l'application Zepp : la série GTR, la série GTS, le T-Rex, le Falcon, le Cheetah, le Balance et l'Amazfit Band. Ces appareils envoient leurs données à Health Connect via Zepp, que FitMesh lit ensuite.",
          pl: "FitMesh obsługuje wszystkie modele device Amazfit, które łączą się z aplikacją Zepp: seria GTR, seria GTS, T-Rex, Falcon, Cheetah, Balance i Amazfit Band. Cała ta sprzęt zapisuje dane do Health Connect poprzez Zepp, który FitMesh następnie odczytuje.",
          tr: "FitMesh, Zepp uygulamasına senkronize edilen tüm Amazfit saatleri ve cilt çubukları ile uyumlu: GTR serisi, GTS serisi, T-Rex, Falcon, Cheetah, Balance ve Amazfit Band. Bu tüm cihazlar Zepp aracılığıyla Health Connect'e verilerini yazdırır ve FitMesh bunları okur.",
          nl: "FitMesh werkt met alle Amazfit horloges en armbandjes die zich in de Zepp-app laten synchroniseren: GTR-serie, GTS-serie, T-Rex, Falcon, Cheetah, Balance en Amazfit Band. Alle deze apparaten schrijven naar Health Connect via Zepp, wat FitMesh dan leest.",
          ja: "FitMeshはZeppアプリと同期できるすべてのAmazfitスマートウォッチおよびバンドと互換性があります：GTRシリーズ、GTSシリーズ、T-Rex、Falcon、Cheetah、Balance、およびAmazfit Band。これらのすべてのデバイスはZeppを通じてHealth Connectに書き込み、FitMeshはそこから読み込みます。",
