          fr: "L'application Zepp se synchronise généralement avec Health Connect lorsqu'on l'ouvre ou sur une synchronisation de fond programmée. Ouvrez l'application Zepp après avoir porté votre Amazfit pour forcer une synchronisation, puis effectuez un rafraîchissement dans FitMesh.",
