          ja: "Zeppアプリは通常、アプリを開いたときまたは定期的なバックグラウンド同期時にHealth Connectと同期します。Amazfitを着用した後、Zeppアプリを開いて同期を強制し、FitMeshで下から引っ張ってリフレッシュしてください。",
