          pt: "Sim. O FitMesh funciona com todos os dispositivos Fitbit que sincronizam com o aplicativo Android do Fitbit, incluindo Charge 5/6, Versa 4, Sense 2, Luxe e Inspire. Qualquer dispositivo Fitbit que escreva dados na Conectividade de Saúde é suportado.",
          fr: "Oui. FitMesh fonctionne avec tous les appareils Fitbit qui synchronisent avec l'application Android Fitbit, y compris Charge 5/6, Versa 4, Sense 2, Luxe et Inspire. Tous les appareils Fitbit qui écrivent des données vers Health Connect sont pris en charge.",
