          de: "Überprüfen Sie, ob die Fitbit-App 'Sleep'-Schreibberechtigungen in Health Connect hat (Health Connect → App-Berechtigungen → Fitbit → Erlaubt zum Schreiben). Stellen Sie auch sicher, dass der Hintergrundsyncing für die Fitbit-App aktiviert ist, damit sie Daten schreiben kann, ohne geöffnet zu werden.",
