          pl: "Sprawdź, czy aplikacja Fitbit ma uprawnienia do pisania dla Sen (Health Connect → Uprawnienia aplikacji → Fitbit → Zezwolone do pisania). Upewnij się również, że włączono synchronizację tła aplikacji Fitbit, aby mogło ona zapisywać dane bez konieczności otworzenia jej ręcznie.",
          tr: "Fitbit uygulamanızın Health Connect'te 'Uyku' yazma iznine sahip olup olmadığını kontrol edin (Health Connect → Uygulama izinleri → Fitbit → Yazma izni kabul edildi). Ayrıca, uygulamayı kendi açmadan veri yazar hale getirebilmek için arka planda senkronizasyonu etkinleştirdiğinizden emin olun.",
