      fr: "FitMesh lit vos courses, sorties vélo, nages et marches enregistrées sur Strava et les affiche sur votre tableau de bord aux côtés des données de vos autres appareils, avec traces GPS, dénivelé, allure moyenne, calories et fréquence cardiaque pour chaque segment. L'envoi des entraînements enregistrés par FitMesh vers Strava est en développement et pas encore disponible dans l'application.",
      pl: "FitMesh odczytuje Twoje biegi, przejażdżki, pływania i spacery zapisane w Strava i pokazuje je w panelu razem z danymi z innych urządzeń, z trasami GPS, przewyższeniem, średnim tempem, kaloriami i tętnem dla każdego segmentu. Wysyłanie treningów zapisanych przez FitMesh do Strava jest w trakcie tworzenia i nie jest jeszcze dostępne w aplikacji.",
      tr: "FitMesh, Strava'da kaydedilen koşularınızı, bisiklet turlarınızı, yüzme seanslarınızı ve yürüyüşlerinizi okur ve diğer cihazlarınızın verileriyle birlikte panelinizde gösterir, her segment için GPS izleri, yükseklik, ortalama hız, kalori ve kalp atış hızı dahil. FitMesh tarafından kaydedilen antrenmanların Strava'ya gönderilmesi geliştirme aşamasındadır ve henüz uygulamada mevcut değildir.",
      nl: "FitMesh leest je op Strava geregistreerde runs, fietstochten, zwemsessies en wandelingen en toont ze in je dashboard naast data van je andere apparaten, met GPS-tracks, hoogteverschil, gemiddeld tempo, calorieën en hartslag per segment. Het versturen van door FitMesh geregistreerde workouts naar Strava is in ontwikkeling en nog niet beschikbaar in de app.",
      ja: "FitMeshはStravaに記録されたランニング、サイクリング、スイミング、ウォーキングを読み取り、他のデバイスのデータと一緒にダッシュボードに表示します。各セグメントのGPSトラック、高度、平均ペース、カロリー、心拍数を含みます。FitMeshで記録したワークアウトをStravaに送信する機能は開発中で、アプリではまだ利用できません。",
      ko: "FitMesh는 Strava에 기록된 달리기, 자전거 타기, 수영, 걷기를 읽어 다른 기기의 데이터와 함께 대시보드에 표시합니다. 각 구간의 GPS 트랙, 고도, 평균 페이스, 칼로리, 심박수를 포함합니다. FitMesh에서 기록한 운동을 Strava로 보내는 기능은 개발 중이며 아직 앱에서 사용할 수 없습니다.",
