          it: "FitMesh legge i dati Polar attraverso Android Health Connect. Nell'app Polar Flow, abilita la sincronizzazione di Health Connect (Profilo → Impostazioni → Health Connect). Poi concedi a FitMesh le permessi di lettura in Health Connect. I tuoi dati del workouts e della salute Polar appariranno su FitMesh alla prossima sincronizzazione.",
