          de: "FitMeshliest die Daten von Polar über Android Health Connect ein. In der Polar Flow-App aktivieren Sie Health Connect-Synchronisation (Profil → Einstellungen → Health Connect). Danach erteilen Sie FitMesh Zugriffsberechtigungen in Health Connect. Ihre Polar-Arbeitsausweise und Gesundheitsdaten erscheinen nach der nächsten Synchronisierung im FitMesh.",
          pt: "O FitMesh lê os dados do Polar através da Android Health Connect. No aplicativo Flow do Polar, habilite a sincronização Health Connect (Perfis → Configurações → Health Connect). Em seguida, conceda permissões de leitura para o FitMesh na Health Connect. Seus dados de treino e saúde Polar aparecerão no FitMesh após a próxima sincronização.",
          fr: "FitMesh lit les données Polar via Android Health Connect. Dans l'application Polar Flow, activez la synchronisation Health Connect (Profil → Paramètres → Health Connect). Ensuite, accordez des permissions de lecture à FitMesh dans Health Connect. Vos données de course et de santé Polar apparaîtront dans FitMesh après le prochain synchronisation.",
