          pt: "O FitMesh lê os dados da Suunto através do Android Health Connect. Ative a sincronização do Health Connect no Suunto App Settings, depois conceda permissões para o FitMesh no Health Connect. A integração Suunto com o Health Connect está atualmente em beta — entre em contato com o suporte se encontrar problemas de sincronização.",
