          nl: "FitMesh leest Suunto gegevens via Android Health Connect op afstand. Schakel Health Connect-synchronisatie in de instellingen van het Suunto-apparaat in, en stuur dan toegang toe aan FitMesh in Health Connect. De integratie van Suunto met Health Connect is op dit moment in beta - neem contact met ondersteuning op als je synchronisatieproblemen ervaring hebt.",
          ja: "FitMeshは、AndroidのHealth Connectを通じてSuuntoのデータを読み取ります。Suuntoアプリの設定でHealth Connectの同期を有効にし、Health ConnectでFitMeshの権限を許可してください。SuuntoのHealth Connect統合は現在ベータ版です—同期に問題が発生した場合はサポートにご連絡ください。",
