        a: {
          it: "L'integrazione con Huawei Health è in sviluppo per la fine del 2026. Una volta disponibile, FitMesh si connetterà tramite l'API Huawei Health Kit, leggendo i dati da tutti i dispositivi HUAWEI Watch e HONOR Watch. Un workaround basato su Health Connect potrebbe funzionare per alcuni utenti nel frattempo.",
          en: "Huawei Health integration is in development for late 2026. Once available, FitMesh will connect via the Huawei Health Kit API, reading data from all HUAWEI Watch and HONOR Watch devices. A Health Connect workaround may work for some users in the interim.",
          es: "La integración de Huawei Health está en desarrollo para finales de 2026. Una vez disponible, FitMesh se conectará a través de la API del Kit de Salud de Huawei Health, leyendo los datos de todos los dispositivos HUAWEI Watch y HONOR Watch. Un workaround de Health Connect podría funcionar temporalmente para algunos usuarios.",
          de: "Die Integration mit Huawei Health wird im Herbst 2026 verfügbar sein. Sobald verfügbar, wird FitMesh über die Huawei Health Kit API verbunden und Daten aus allen HUAWEI Watch und HONOR Watch-Geräten lesen können. Ein Workaround für Health Connect könnte in der Zwischenzeit einige Benutzer betreffen.",
          pt: "A integração do Huawei Health está em desenvolvimento para o final de 2026. Uma vez disponível, o FitMesh se conectará através da API Kit Huawei Health, lendo dados de todos os dispositivos HUAWEI Watch e HONOR Watch. Um workaround com a Health Connect pode funcionar temporariamente para alguns usuários.",
          fr: "L'intégration Huawei Health sera disponible à partir de la fin 2026. Une fois disponible, FitMesh se connectera via l'API Kit de santé Huawei Health et lira les données des appareils HUAWEI Watch et HONOR Watch. Une solution d'-workaround basée sur Health Connect pourrait fonctionner pour certains utilisateurs temporairement.",
          pl: "Integracja Huawei Health z oprogramowaniem_fitmesh jest w fazie rozwijania i powinna być dostępna do końca 2026 roku. Po dostarczeniu, FitMesh połączy się za pomocą interfejsu API Kit Huawei Health, przeczytując dane z wszystkich urządzeń HUAWEI Watch oraz HONOR Watch. Możliwe, że workaround dla Health Connect będzie działał do czasu dostępności oficjalnego rozwiązania.",
          tr: "Huawei Health integrasyonu 2026 sonunda geliştirilmeye başlanacak. Mevcut olunca, FitMesh Huawei Health Kit API üzerinden bağlanarak tüm HUAWEI Watch ve HONOR Watch cihazlardan verileri okuyacaktır. Arasında bir çözüm olan bir Health Connect uygulaması bazı kullanıcılar için geçici olarak işe yarayabilir.",
          nl: "Integratie met Huawei Health is in ontwikkeling voor het eind van 2026. Zodra deze beschikbaar is, zal FitMesh via de Huawei Health Kit API verbinding maken en data lezen uit alle HUAWEI Watch en HONOR Watch apparaten. Een workaround voor Health Connect kan tijdelijk werken voor sommige gebruikers.",
          ja: "Huawei Healthの統合は2026年末に開発予定です。利用可能になると、FitMeshはHuawei Health Kit APIを通じて、すべてのHUAWEI WatchおよびHONOR Watchデバイスからのデータを読み取ります。その間、一部のユーザーにはHealth Connectのワークアラウンドが機能する可能性があります。",
          ko: "Huawei Health의 통합은 2026년 말에 개발될 예정입니다. 제공되면 FitMesh는 Huawei Health Kit API를 통해 모든 HUAWEI Watch 및 HONOR Watch 기기에서 데이터를 읽을 수 있습니다. 이 기간 동안 일부 사용자에게 Health Connect 대안이 작동할 수 있습니다.",
        },
