          es: "FitMesh planifica compatibilizar todos los modelos de HUAWEI Watch y HONOR Watch que sincronizan con Huawei Health: series GT de HUAWEI Watch, 4, Fit, Band 9, y modelos de HONOR Band y Watch.",
          de: "FitMesh plant, alle HUAWEI Watch und HONOR Watch-Modelle zu unterstützen, die mit Huawei Health synchronisiert werden: GT-Serien-Uhren, Watch 4, Watch Fit, Band 9 sowie HONOR-Band- und -Uhren-Modelle.",
          pt: "O FitMesh planeja suportar todos os modelos de HUAWEI Watch e HONOR Watch que sincronizam com o Huawei Health: séries GT da linha Watch, Watch 4, Watch Fit, Band 9 e modelos HONOR Band e Watch.",
          fr: "FitMesh prévoit de soutenir toutes les modèles de HUAWEI Watch et HONOR Watch qui se synchronisent avec Huawei Health : série GT, 4e génération, Fit, Band 9, et modèles HONOR Band et Watch.",
          pl: "FitMesh planuje wsparcie dla wszystkich modeli HUAWEI Watch i HONOR Watch, które synchronizują dane z Huawei Health: seria Watch GT, Watch 4, Watch Fit, Band 9 oraz modele HONOR Band i HONOR Watch.",
          tr: "FitMesh, Huawei Health ile senkronize edilen tüm HUAWEI Watch ve HONOR Watch modellerini destekleme planı var: GT cihazı serisi, 4. watch, Fit watch, Band 9 ve HONOR Band ve Watch modelleri.",
