          pt: "Sim. O FitMesh lê os dados de passos registrados pelo pedometro embutido no seu telefone Android através da Health Connect. Seu telefone contabiliza automaticamente os passos usando o acelerômetro — nenhum dispositivo wearable é necessário. Apenas conceda acesso de leitura ao FitMesh para 'Passos' na Health Connect.",
