          pl: "Tak. FitMesh odczytuje dane dotyczące kroków z pomiaru wewnętrzowego pedometru twojego telefonu Android poprzez Health Connect. Twój telefon automatycznie liczy kroki, korzystając ze swojej przyspiesznika — bez potrzeby używania naocznych urządzeń. Ale musisz udzielić dostępu do 'Kroków' w Health Connect.",
          tr: "Evet. FitMesh, telefonunuzda bulunan pedometer verilerini Health Connect aracılığıyla okuyarak adımlarınızı izler. Telefonunuz sürekli hareket sensörü kullanarak adımları saymaya başlarken, her wearable gerektirmez. Yalnızca FitMesh'ü 'Adım Sayımı' için Okuma Erişimi verin.",
          nl: "Ja. FitMesh leest stapgegevens die worden opgeslagen door de ingebouwde pedometer van je Android-telefoon via Health Connect. Je telefoon telt stapels automatisch met behulp van zijn accelerometers - geen draagbaar apparaat vereist. Geef FitMesh alleen toegang tot 'Stappen' in Health Connect om deze gegevens te lezen.",
          ja: "はい。FitMeshは、Androidスマートフォンの内蔵の歩数計が記録したステップデータをHealth Connectを通じて読み取ります。スマートフォンは加速度センサーを使用して自動的にステップをカウントします。ウェアラブルは不要です。FitMeshにHealth Connectの「ステップ」への読み取りアクセスを許可するだけです。",
