          de: "Welche Gesundheitsdaten werden von FitMesh vom Colmi Ring gelesen?",
          pt: "Qual dados de saúde o FitMesh lê do Colmi Ring?",
          fr: "Quels données de santé lit FitMesh depuis le Colmi Ring ?",
