          tr: "Colmi Çengeminde Hangi Sağlık Verilerini Okuyor FitMesh?",
          nl: "Wat gezondheidsdata leest FitMesh af vanuit de Colmi Ring?",
          ja: "FitMeshはColmi Ringからどの健康データを読み取れますか？",
          ko: "FitMesh는 Colmi Ring에서 어떤 건강 데이터를 읽나요?",
