          en: "Does Colmi Ring need the CRing or Colmi app to work with FitMesh?",
          es: "¿Necesita el Colmi Ring el CRing o la app de Colmi para funcionar con FitMesh?",
          de: "Muss der Colmi Ring CRing oder die Colmi App zur Arbeit mit FitMesh haben?",
          pt: "O Colmi Ring precisa do CRing ou do app Colmi para funcionar com o FitMesh?",
