          de: "FitMesh für iPhone liest Daten aus Apple Health direkt über HealthKit ein. Auf iOS erteile FitMesh Zugriff in Einstellungen → Datenschutz & Sicherheit → Gesundheit → FitMesh. Dein Apple Watch, dein iPhone und alle anderen HealthKit-kompatiblen Apps beitragen zu den Daten von FitMesh automatisch.",
          pt: "O FitMesh para iPhone lê os dados do Apple Health diretamente usando a HealthKit. No iOS, conceda acesso ao FitMesh nas Configurações → Privacidade & Segurança → Saúde → FitMesh. Seu Apple Watch, iPhone e quaisquer outros aplicativos compatíveis com HealthKit contribuirão automaticamente com seus dados para o FitMesh.",
