          de: "Ja. Wenn FitMesh auf deinem iPhone installiert ist und Zugriff auf Apple Health hat, liest es alle von deinem Apple Watch aufgezeichneten Daten ein – einschließlich Aktivitätsringe, Herzkraft, Schlaf (watchOS 9+), EKG, Unfallwarnung und Fitness-Trainings – über das HealthKit-Framework.",
          pt: "Sim. Quando o FitMesh é instalado em seu iPhone com acesso ao Apple Health, ele lê todos os dados registrados pelo seu Apple Watch — incluindo anéis de atividade, ritmo cardíaco, sono (watchOS 9+), ECG, detecção de queda e treinos de fitness — através do framework HealthKit.",
