          tr: "Evet. FitMesh'i iPhone'da HealthKit erişimi olan bir şekilde kurduğunuzda, aygıtınız tarafından kaydedilen tüm verileri — aktivite halkaları, kalp hızı (watchOS 9+ ile uyku), EKG, çarpmaya karşı uyarılar ve eğitimsel eğitimler dahil olmak üzere — HealthKit çerçevesini kullanarak okur.",
